var targetTitle = Tama.Args.Get(args, "target", "");
var sourceTitle = Tama.Args.Get(args, "source", "");
var ids = ((object[])args["ids"]).Select(o => new ElementId(Convert.ToInt32(o))).ToList();
Document target = null, source = null;
foreach (Document d in app.Documents) { if (d.IsLinked) continue; if (d.Title == targetTitle) target = d; if (d.Title == sourceTitle) source = d; }
if (target == null || source == null) throw new Exception("Source or target not open");
var tLevels = new FilteredElementCollector(target).OfClass(typeof(Level)).Cast<Level>().ToDictionary(l => l.Name, l => l.Id);
var srcScheds = new FilteredElementCollector(source).OfClass(typeof(ViewSchedule)).Cast<ViewSchedule>().Where(v => !v.IsTemplate).ToList();
var res = new List<object>();
using (var t = new Transaction(target, "Restore schedule filters")) {
  t.Start();
  foreach (var id in ids) {
    var vs = (ViewSchedule)target.GetElement(id);
    var tdef = vs.Definition;
    if (tdef.GetFilterCount() > 0) { res.Add(new { vs.Name, added = new List<string> { "already has filters - skipped" } }); continue; }
    var src = srcScheds.FirstOrDefault(s => s.Name == vs.Name);
    if (src == null) throw new Exception("No source schedule " + vs.Name);
    var sdef = src.Definition;
    var added = new List<string>();
    for (int i = 0; i < sdef.GetFilterCount(); i++) {
      var sf = sdef.GetFilter(i);
      var sField = sdef.GetField(sf.FieldId);
      ScheduleField tField = null;
      for (int j = 0; j < tdef.GetFieldCount(); j++) { var f = tdef.GetField(j); if (f.ColumnHeading == sField.ColumnHeading && f.FieldType == sField.FieldType) { tField = f; break; } }
      if (tField == null) throw new Exception(vs.Name + ": field " + sField.ColumnHeading + " missing");
      ScheduleFilter nf;
      if (sf.IsElementIdValue) {
        var lvlName = source.GetElement(sf.GetElementIdValue())?.Name;
        if (lvlName == null || !tLevels.ContainsKey(lvlName)) throw new Exception(vs.Name + ": level " + lvlName + " not in target");
        nf = new ScheduleFilter(tField.FieldId, sf.FilterType, tLevels[lvlName]);
        added.Add(sField.ColumnHeading + " = " + lvlName);
      } else if (sf.IsStringValue) { nf = new ScheduleFilter(tField.FieldId, sf.FilterType, sf.GetStringValue()); added.Add(sField.ColumnHeading + " " + sf.FilterType + " " + sf.GetStringValue()); }
      else { nf = new ScheduleFilter(tField.FieldId, sf.FilterType); added.Add(sField.ColumnHeading + " " + sf.FilterType); }
      tdef.AddFilter(nf);
    }
    res.Add(new { vs.Name, added });
  }
  t.Commit();
}
var verify = ids.Select(id => { var vs = (ViewSchedule)target.GetElement(id); var b = vs.GetTableData().GetSectionData(SectionType.Body); var rows = new List<string>(); for (int r = 1; r < b.NumberOfRows; r++) { var c = new List<string>(); foreach (int k in new[] { 0, 1, 2, 4 }) if (k < b.NumberOfColumns) c.Add(vs.GetCellText(SectionType.Body, r, k)); rows.Add(string.Join(" | ", c)); } return new { vs.Name, rows }; }).ToList();
return new { res, verify };
